struct Params {
  length: u32,
  output_offset: u32,
  first: f32,
  second: f32,
};

@group(0) @binding(0) var<read> left_values: array<f32>;
@group(0) @binding(1) var<read> right_values: array<f32>;
@group(0) @binding(2) var<read_write> output_values: array<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@compute @workgroup_size(1, 1, 1)
@override_required(WORKGROUP_SIZE = 1)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
  let i: u32 = global_id.x;
  if (i >= params.length) {
    return;
  }
  let x = left_values[i];
  let y = right_values[i];
  let result = (x * x) * x;
  output_values[params.output_offset + i] = result;
}

