    return;
  }
  let x : f32 = left_values[i];
  let y : f32 = right_values[i];
  let result : f32;
  if (x >= params.first) {
    result = x - y;
  } else {
    result = y - x;
  }
  output_values[params.output_offset + i] = result;
}

