const promptBytes=await readFile(root+'corpus-v1/selection/prompts.jsonl');
assert.equal(sha256(promptBytes),audit.selectionPromptFileSha256);
assert.equal(sha256(await readFile(root+'../campaign/tools/lib/wgsl-writer-semantic-harness.js')),audit.parserSourceSha256);
const rows=promptBytes.toString().trim().split('\n').map(JSON.parse),ns=await openIsolatedNamespace();
try {
const outputs=audit.records.map(record=>{const row=rows.find(r=>r.taskId===record.taskId),prompt=ns.buildWgslWriterPrompt(row,{responseContract:'complete_wgsl_compute_shader_only_v1'}),parsed=ns.parseCompleteWgslResponse(record.source,audit.parserContract,row.interfaceContract);assert.equal(prompt,row.prompt);assert.equal(sha256(prompt),record.promptSha256);assert.equal(sha256(record.source),record.outputSha256);assert.equal(replayHash(parsed),record.parserOutputSha256);return {id:record.id,promptSha256:sha256(prompt),outputSha256:sha256(record.source),parserOutputSha256:replayHash(parsed),ok:parsed.ok,violations:parsed.violations};});
const cases=audit.validDeclarationCases.map(c=>{const parsed=ns.parseCompleteWgslResponse(c.source,audit.parserContract,rows[0].interfaceContract);assert.deepEqual(parsed,c.parserOutput);return {id:c.id,ok:parsed.ok,violations:parsed.violations};});
console.log(JSON.stringify({checkedSelectionOutputs:outputs.length,outputs,cases,gpuInvocations:0,confirmationOutputsInspected:false,confirmationOracleFilesRead:false},null,2));
} finally {await ns.close();}
